-- ANGELCARE Flashcards OS — Ultra Mega ZIP 3
-- External Production Command Forge, Windows Product Vault, Quality and Immutable Releases.
-- Additive consolidated migration. Requires UMZ1 + UMZ2.
begin;
create extension if not exists pgcrypto;
create schema if not exists flashcards_os;

-- Command authority -----------------------------------------------------------
create table if not exists flashcards_os.command_templates (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', template_key text not null, label text not null, output_type text not null, version_no integer not null default 1, section_contract jsonb not null default '[]', negative_constraints text[] not null default '{}', delivery_manifest jsonb not null default '{}', status text not null default 'active' check(status in('draft','active','disabled','archived')), created_by text null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_key,template_key,version_no));
create table if not exists flashcards_os.command_output_profiles (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', profile_key text not null, label text not null, output_type text not null check(output_type in('print_pdf','digital_pdf','mp4','classroom','parent_guide','teacher_guide','promotional_preview','editable_source')), technical_contract jsonb not null default '{}', required_return_items text[] not null default '{}', status text not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_key,profile_key));
create table if not exists flashcards_os.production_commands (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', code text not null, collection_id text not null, design_id uuid not null references flashcards_os.product_designs(id) on update cascade on delete restrict, design_version integer not null default 1, output_type text not null check(output_type in('print_pdf','digital_pdf','mp4','classroom','parent_guide','teacher_guide','promotional_preview','editable_source')), edition text not null, variant text not null, external_profile text not null, status text not null default 'draft' check(status in('draft','compiling','compiled','validation_required','human_review','corrections_required','approved','copied','externally_submitted','production_active','returned','closed','superseded')), version_no integer not null default 1, title text not null, mission text not null default '', sections jsonb not null default '[]', deterministic_findings text[] not null default '{}', advisory_findings text[] not null default '{}', approval_note text null, approved_by text null, approved_at timestamptz null, copied_at timestamptz null, superseded_by_id uuid null references flashcards_os.production_commands(id) on update cascade on delete restrict, created_by text null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_key,code));
create table if not exists flashcards_os.production_command_versions (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', command_id uuid not null references flashcards_os.production_commands(id) on update cascade on delete restrict, version_no integer not null, title text not null, mission text not null, sections jsonb not null default '[]', content_hash text not null, change_note text null, created_by text null, created_at timestamptz not null default now(), unique(tenant_key,command_id,version_no));
create table if not exists flashcards_os.production_command_sections (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', command_id uuid not null references flashcards_os.production_commands(id) on update cascade on delete restrict, version_no integer not null default 1, section_key text not null, title text not null, order_no integer not null, content text not null, locked boolean not null default false, validation_status text not null default 'pending' check(validation_status in('pending','valid','warning','blocking')), findings text[] not null default '{}', updated_by text null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_key,command_id,version_no,section_key));
create table if not exists flashcards_os.command_validations (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', command_id uuid not null references flashcards_os.production_commands(id) on update cascade on delete restrict, version_no integer not null, validation_type text not null check(validation_type in('deterministic','openrouter_critic','human')), status text not null check(status in('passed','warning','blocked')), findings jsonb not null default '[]', model_used text null, run_id uuid null, validated_by text null, created_at timestamptz not null default now());
create table if not exists flashcards_os.command_approvals (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', command_id uuid not null references flashcards_os.production_commands(id) on update cascade on delete restrict, version_no integer not null, decision text not null check(decision in('approved','rejected','rework')), note text not null, approver_id text not null, approver_name text not null, approver_role text null, created_at timestamptz not null default now());
create table if not exists flashcards_os.command_copy_events (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', command_id uuid not null references flashcards_os.production_commands(id) on update cascade on delete restrict, copy_scope text not null check(copy_scope in('all','section','txt','markdown')), section_key text null, actor_id text not null, actor_name text not null, created_at timestamptz not null default now());
create table if not exists flashcards_os.command_exports (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', command_id uuid not null references flashcards_os.production_commands(id) on update cascade on delete restrict, format text not null check(format in('txt','markdown')), version_no integer not null, content_hash text not null, exported_by text not null, created_at timestamptz not null default now());

-- External production operations ---------------------------------------------
create table if not exists flashcards_os.external_tool_profiles (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', profile_key text not null, label text not null, environment_type text not null, instruction_overrides jsonb not null default '{}', integration_enabled boolean not null default false check(integration_enabled=false), status text not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_key,profile_key));
create table if not exists flashcards_os.external_production_jobs (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', code text not null, command_id uuid not null references flashcards_os.production_commands(id) on update cascade on delete restrict, collection_id text not null, output_type text not null, producer text not null, external_environment text not null, external_reference text null, status text not null default 'prepared' check(status in('prepared','command_approved','submitted','accepted_by_producer','in_production','questions_received','correction_requested','awaiting_return','files_returned','under_review','accepted','rejected','closed')), target_delivery_date timestamptz null, estimated_cost numeric(14,2) not null default 0, actual_cost numeric(14,2) not null default 0, correction_cycles integer not null default 0, blocker text null, returned_file_count integer not null default 0, created_by text null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_key,code));
create table if not exists flashcards_os.external_production_events (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', job_id uuid not null references flashcards_os.external_production_jobs(id) on update cascade on delete restrict, event_type text not null, detail text not null default '', actor_name text null, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table if not exists flashcards_os.external_production_questions (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', job_id uuid not null references flashcards_os.external_production_jobs(id) on update cascade on delete restrict, question text not null, answer text null, status text not null default 'open' check(status in('open','answered','closed')), raised_by text null, answered_by text null, created_at timestamptz not null default now(), answered_at timestamptz null);
create table if not exists flashcards_os.external_correction_cycles (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', job_id uuid not null references flashcards_os.external_production_jobs(id) on update cascade on delete restrict, cycle_no integer not null, source_review_id uuid null, corrective_command text not null, preserve_instructions text[] not null default '{}', expected_files text[] not null default '{}', status text not null default 'requested' check(status in('requested','submitted','returned','verified','closed')), created_by text null, created_at timestamptz not null default now(), closed_at timestamptz null, unique(tenant_key,job_id,cycle_no));

-- Sovereign Windows Vault -----------------------------------------------------
create table if not exists flashcards_os.storage_nodes (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', node_key text not null, label text not null, status text not null default 'unconfigured' check(status in('online','degraded','offline','unconfigured')), last_heartbeat_at timestamptz null, total_bytes bigint not null default 0, used_bytes bigint not null default 0, free_bytes bigint not null default 0, active_transfers integer not null default 0, failed_transfers integer not null default 0, quarantine_count integer not null default 0, root_alias text not null default 'FLASHCARDS_OS_VAULT', version text null, metadata jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_key,node_key));
create table if not exists flashcards_os.storage_policies (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', policy_key text not null, label text not null, allowed_extensions text[] not null default '{}', allowed_mime_types text[] not null default '{}', max_bytes bigint not null, chunk_size_bytes integer not null, require_checksum boolean not null default true, quarantine_unknown boolean not null default true, retention_days integer null, status text not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_key,policy_key));
create table if not exists flashcards_os.upload_sessions (
 id uuid primary key, tenant_key text not null default 'angelcare-internal', code text not null, collection_id text not null, command_id uuid null references flashcards_os.production_commands(id) on update cascade on delete restrict, external_job_id uuid null references flashcards_os.external_production_jobs(id) on update cascade on delete restrict, file_name text not null, classification text not null, mime_type text not null, total_bytes bigint not null check(total_bytes>0), chunk_size integer not null check(chunk_size>0), uploaded_bytes bigint not null default 0, uploaded_parts integer not null default 0, total_parts integer not null check(total_parts>0), status text not null default 'initiated' check(status in('initiated','uploading','paused','finalising','completed','cancelled','expired','failed','quarantined')), checksum_expected text null, checksum_actual text null, storage_node_id text null, storage_object_id uuid null, expires_at timestamptz not null, completed_at timestamptz null, error_message text null, created_by text null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_key,code));
create table if not exists flashcards_os.upload_parts (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', upload_session_id uuid not null references flashcards_os.upload_sessions(id) on update cascade on delete restrict, part_number integer not null check(part_number>0), size_bytes integer not null check(size_bytes>0), checksum_sha256 text not null, status text not null default 'received' check(status in('received','verified','rejected')), received_at timestamptz not null default now(), unique(tenant_key,upload_session_id,part_number));
create table if not exists flashcards_os.storage_objects (
 id uuid primary key, tenant_key text not null default 'angelcare-internal', code text not null, collection_id text not null, version_no integer not null default 1, classification text not null, file_name text not null, mime_type text not null, size_bytes bigint not null check(size_bytes>=0), checksum_sha256 text not null, status text not null default 'working' check(status in('working','review','approved','quarantined','superseded','archived')), source_package_id uuid null, deliverable_id uuid null, node_key text not null, root_alias text not null, storage_locator text not null, superseded_by_id uuid null references flashcards_os.storage_objects(id) on update cascade on delete restrict, created_by text null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_key,code), unique(tenant_key,node_key,storage_locator));
create table if not exists flashcards_os.storage_object_versions (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', storage_object_id uuid not null references flashcards_os.storage_objects(id) on update cascade on delete restrict, version_no integer not null, checksum_sha256 text not null, size_bytes bigint not null, storage_locator text not null, status text not null, created_by text null, created_at timestamptz not null default now(), unique(tenant_key,storage_object_id,version_no));
create table if not exists flashcards_os.storage_health_events (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', node_key text not null, status text not null, capacity jsonb not null default '{}', active_transfers integer not null default 0, failed_transfers integer not null default 0, quarantine_count integer not null default 0, error_message text null, created_at timestamptz not null default now());
create table if not exists flashcards_os.transfer_events (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', upload_session_id uuid null references flashcards_os.upload_sessions(id) on update cascade on delete restrict, event_type text not null, part_number integer null, bytes bigint not null default 0, checksum text null, detail text null, created_at timestamptz not null default now());
create table if not exists flashcards_os.quarantine_events (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', storage_object_id uuid null references flashcards_os.storage_objects(id) on update cascade on delete restrict, upload_session_id uuid null references flashcards_os.upload_sessions(id) on update cascade on delete restrict, reason text not null, resolution text null, status text not null default 'open' check(status in('open','released','destroyed','archived')), decided_by text null, created_at timestamptz not null default now(), decided_at timestamptz null);

-- Source packages and deliverables -------------------------------------------
create table if not exists flashcards_os.source_packages (
 id uuid primary key, tenant_key text not null default 'angelcare-internal', code text not null, collection_id text not null, command_id uuid not null references flashcards_os.production_commands(id) on update cascade on delete restrict, external_job_id uuid not null references flashcards_os.external_production_jobs(id) on update cascade on delete restrict, version_no integer not null default 1, producer text not null, environment text not null, storage_object_ids uuid[] not null default '{}', manifest_complete boolean not null default false, review_status text not null default 'pending' check(review_status in('pending','review','approved','rejected')), approved_by text null, approved_at timestamptz null, superseded_by_id uuid null references flashcards_os.source_packages(id) on update cascade on delete restrict, created_by text null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_key,code));
create table if not exists flashcards_os.source_package_files (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', source_package_id uuid not null references flashcards_os.source_packages(id) on update cascade on delete restrict, storage_object_id uuid not null references flashcards_os.storage_objects(id) on update cascade on delete restrict, role text not null, required boolean not null default true, created_at timestamptz not null default now(), unique(tenant_key,source_package_id,storage_object_id));
create table if not exists flashcards_os.deliverables (
 id uuid primary key, tenant_key text not null default 'angelcare-internal', code text not null, collection_id text not null, command_id uuid not null references flashcards_os.production_commands(id) on update cascade on delete restrict, external_job_id uuid not null references flashcards_os.external_production_jobs(id) on update cascade on delete restrict, source_package_id uuid null references flashcards_os.source_packages(id) on update cascade on delete restrict, output_type text not null, version_no integer not null default 1, storage_object_ids uuid[] not null default '{}', review_status text not null default 'pending' check(review_status in('pending','review','approved','rejected')), release_id uuid null, superseded_by_id uuid null references flashcards_os.deliverables(id) on update cascade on delete restrict, received_at timestamptz not null default now(), approved_by text null, approved_at timestamptz null, created_by text null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_key,code));
create table if not exists flashcards_os.deliverable_files (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', deliverable_id uuid not null references flashcards_os.deliverables(id) on update cascade on delete restrict, storage_object_id uuid not null references flashcards_os.storage_objects(id) on update cascade on delete restrict, role text not null, created_at timestamptz not null default now(), unique(tenant_key,deliverable_id,storage_object_id));

-- Quality and correction ------------------------------------------------------
create table if not exists flashcards_os.quality_reviews (
 id uuid primary key, tenant_key text not null default 'angelcare-internal', code text not null, deliverable_id uuid not null references flashcards_os.deliverables(id) on update cascade on delete restrict, status text not null default 'draft' check(status in('draft','active','correction_required','approved','rejected','closed')), disciplines jsonb not null default '[]', findings jsonb not null default '[]', blockers integer not null default 0, created_by text null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_key,code));
create table if not exists flashcards_os.quality_review_disciplines (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', review_id uuid not null references flashcards_os.quality_reviews(id) on update cascade on delete restrict, discipline text not null check(discipline in('integrity','manifest','content','pedagogy','language','brand','technical','source_package','rights','release')), status text not null default 'pending' check(status in('pending','passed','failed','waived')), reviewer_id text null, reviewer_name text null, note text null, decided_at timestamptz null, unique(tenant_key,review_id,discipline));
create table if not exists flashcards_os.quality_findings (
 id uuid primary key, tenant_key text not null default 'angelcare-internal', review_id uuid not null references flashcards_os.quality_reviews(id) on update cascade on delete restrict, discipline text not null, severity text not null check(severity in('observation','minor','major','release_blocker','critical')), title text not null, detail text not null, locator text null, expected_correction text not null, responsible_party text not null, due_date timestamptz null, status text not null default 'open' check(status in('open','acknowledged','resolved','waived')), resolution text null, resolved_by text null, resolved_at timestamptz null, created_by text null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists flashcards_os.quality_finding_events (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', finding_id uuid not null references flashcards_os.quality_findings(id) on update cascade on delete restrict, event_type text not null, detail text not null, actor_name text null, created_at timestamptz not null default now());

-- Immutable product release --------------------------------------------------
create table if not exists flashcards_os.product_releases (
 id uuid primary key, tenant_key text not null default 'angelcare-internal', code text not null, collection_id text not null, collection_version integer not null, design_id uuid not null references flashcards_os.product_designs(id) on update cascade on delete restrict, command_id uuid not null references flashcards_os.production_commands(id) on update cascade on delete restrict, source_package_id uuid not null references flashcards_os.source_packages(id) on update cascade on delete restrict, deliverable_ids uuid[] not null default '{}', status text not null default 'draft' check(status in('draft','assembly','validation','approval_requested','approved','released','commercially_active','superseded','retired','archived')), version_no integer not null default 1, blocking_reasons text[] not null default '{}', approval_note text null, approved_by text null, approved_at timestamptz null, released_at timestamptz null, supersedes_release_id uuid null references flashcards_os.product_releases(id) on update cascade on delete restrict, superseded_by_id uuid null references flashcards_os.product_releases(id) on update cascade on delete restrict, created_by text null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_key,code));
create table if not exists flashcards_os.product_release_assets (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', release_id uuid not null references flashcards_os.product_releases(id) on update cascade on delete restrict, storage_object_id uuid not null references flashcards_os.storage_objects(id) on update cascade on delete restrict, asset_role text not null, immutable_checksum text not null, created_at timestamptz not null default now(), unique(tenant_key,release_id,storage_object_id));
create table if not exists flashcards_os.release_approvals (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', release_id uuid not null references flashcards_os.product_releases(id) on update cascade on delete restrict, discipline text not null, decision text not null check(decision in('approved','rejected','rework')), note text not null, approver_id text not null, approver_name text not null, created_at timestamptz not null default now());
create table if not exists flashcards_os.release_events (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', release_id uuid not null references flashcards_os.product_releases(id) on update cascade on delete restrict, event_type text not null, detail text null, actor_name text null, created_at timestamptz not null default now());
create table if not exists flashcards_os.download_events (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', storage_object_id uuid null references flashcards_os.storage_objects(id) on update cascade on delete restrict, object_key text not null, actor_id text not null, actor_name text not null, range_requested text null, bytes_sent bigint not null default 0, created_at timestamptz not null default now());
create table if not exists flashcards_os.retention_events (
 id uuid primary key default gen_random_uuid(), tenant_key text not null default 'angelcare-internal', storage_object_id uuid not null references flashcards_os.storage_objects(id) on update cascade on delete restrict, action text not null check(action in('archive','restore','retain','destroy_requested','destroyed')), reason text not null, actor_name text not null, created_at timestamptz not null default now());
create table if not exists flashcards_os.integrity_reconciliation_runs (
 id uuid primary key, tenant_key text not null default 'angelcare-internal', node_key text not null, status text not null check(status in('running','completed','failed')), result jsonb not null default '{}', started_at timestamptz not null default now(), completed_at timestamptz null, created_by text null, created_at timestamptz not null default now());

-- Updated-at triggers ---------------------------------------------------------
do $$ declare t text; begin foreach t in array array['command_templates','command_output_profiles','production_commands','production_command_sections','external_tool_profiles','external_production_jobs','storage_nodes','storage_policies','upload_sessions','storage_objects','source_packages','deliverables','quality_reviews','quality_findings','product_releases'] loop execute format('drop trigger if exists trg_fc_%I_updated_at on flashcards_os.%I',t,t); execute format('create trigger trg_fc_%I_updated_at before update on flashcards_os.%I for each row execute function flashcards_os.touch_updated_at()',t,t); end loop; end $$;

-- Release immutability --------------------------------------------------------
create or replace function flashcards_os.guard_released_asset_mutation() returns trigger language plpgsql as $$ begin if old.status in ('released','commercially_active','superseded','retired','archived') and (new.command_id<>old.command_id or new.source_package_id<>old.source_package_id or new.deliverable_ids<>old.deliverable_ids or new.collection_version<>old.collection_version) then raise exception 'Released product composition is immutable; create a new release version.'; end if; return new; end $$;
drop trigger if exists trg_fc_product_release_immutable on flashcards_os.product_releases;
create trigger trg_fc_product_release_immutable before update on flashcards_os.product_releases for each row execute function flashcards_os.guard_released_asset_mutation();
create or replace function flashcards_os.recount_quality_blockers() returns trigger language plpgsql as $$ declare rid uuid; begin rid=coalesce(new.review_id,old.review_id); update flashcards_os.quality_reviews set blockers=(select count(*) from flashcards_os.quality_findings where review_id=rid and severity in('release_blocker','critical') and status not in('resolved','waived')), findings=(select coalesce(jsonb_agg(jsonb_build_object('id',id,'reviewId',review_id,'discipline',discipline,'severity',severity,'title',title,'detail',detail,'locator',locator,'expectedCorrection',expected_correction,'responsibleParty',responsible_party,'dueDate',due_date,'status',status,'resolution',resolution) order by created_at),'[]'::jsonb) from flashcards_os.quality_findings where review_id=rid) where id=rid; return coalesce(new,old); end $$;
drop trigger if exists trg_fc_recount_quality_blockers on flashcards_os.quality_findings;
create trigger trg_fc_recount_quality_blockers after insert or update or delete on flashcards_os.quality_findings for each row execute function flashcards_os.recount_quality_blockers();

-- RLS and service views -------------------------------------------------------
do $$ declare t text; begin foreach t in array array['command_templates','command_output_profiles','production_commands','production_command_versions','production_command_sections','command_validations','command_approvals','command_copy_events','command_exports','external_tool_profiles','external_production_jobs','external_production_events','external_production_questions','external_correction_cycles','storage_nodes','storage_policies','upload_sessions','upload_parts','storage_objects','storage_object_versions','storage_health_events','transfer_events','quarantine_events','source_packages','source_package_files','deliverables','deliverable_files','quality_reviews','quality_review_disciplines','quality_findings','quality_finding_events','product_releases','product_release_assets','release_approvals','release_events','download_events','retention_events','integrity_reconciliation_runs'] loop execute format('alter table flashcards_os.%I enable row level security',t); execute format('drop policy if exists tenant_read on flashcards_os.%I',t); execute format('create policy tenant_read on flashcards_os.%I for select to authenticated using (tenant_key=coalesce(auth.jwt()->>''tenant_key'',''''))',t); end loop; end $$;

create or replace view public.fc_os_command_templates as select * from flashcards_os.command_templates;
create or replace view public.fc_os_command_output_profiles as select * from flashcards_os.command_output_profiles;
create or replace view public.fc_os_production_commands as select c.*, coalesce(col.code,'') collection_code, coalesce(col.name,'Collection') collection_name, coalesce(d.code,'') design_code from flashcards_os.production_commands c left join flashcards_os.collections col on col.id::text=c.collection_id left join flashcards_os.product_designs d on d.id=c.design_id;
create or replace view public.fc_os_production_command_versions as select * from flashcards_os.production_command_versions;
create or replace view public.fc_os_production_command_sections as select * from flashcards_os.production_command_sections;
create or replace view public.fc_os_command_validations as select * from flashcards_os.command_validations;
create or replace view public.fc_os_command_approvals as select * from flashcards_os.command_approvals;
