do $$ declare v text; begin foreach v in array array['command_templates','command_output_profiles','production_commands','production_command_versions','production_command_sections','command_validations','command_approvals','command_copy_events','command_exports','external_tool_profiles','external_production_jobs','external_production_events','external_production_questions','external_correction_cycles','storage_nodes','storage_policies','upload_sessions','upload_parts','storage_objects','storage_object_versions','storage_health_events','transfer_events','quarantine_events','source_packages','source_package_files','deliverables','deliverable_files','quality_reviews','quality_review_disciplines','quality_findings','quality_finding_events','product_releases','product_release_assets','release_approvals','release_events','download_events','retention_events','integrity_reconciliation_runs'] loop execute format('revoke all on public.fc_os_%I from authenticated, anon',v); execute format('grant all on public.fc_os_%I to service_role',v); end loop; end $$;

